# hello.S - RISC-V64 (RV64I only) guest for the Reforge Windows-format fixture.
#
# Behaviour: printf(msg) through the msvcrt.dll import, then ExitProcess(0)
# through the kernel32.dll import. The message is generated by the builder
# (scripts/build_fixtures.sh passes --string msg=...), see ABI.md.
#
# @import msvcrt.dll!printf
# @import kernel32.dll!ExitProcess

    .section .rdata,"a",@progbits
    .include "strings.inc"          # defines msg: .asciz <MESSAGE>

    .text
    .globl _start
    .type _start,@function
_start:
    addi sp, sp, -16               # keep sp 16-byte aligned (RISC-V psABI)
    sd   ra, 0(sp)                 # save return address on guest stack

.Lmsg:
    auipc a0, %pcrel_hi(msg)       # a0 = &msg
    addi  a0, a0, %pcrel_lo(.Lmsg)

.Lprintf:
    auipc t0, %pcrel_hi(__imp_printf)
    ld    t0, %pcrel_lo(.Lprintf)(t0)   # t0 = IAT slot for msvcrt.dll!printf
    jalr  ra, 0(t0)                     # printf(&msg)

    ld    ra, 0(sp)
    addi  sp, sp, 16
    li    a0, 0                    # exit status 0

.Lexit:
    auipc t0, %pcrel_hi(__imp_ExitProcess)
    ld    t0, %pcrel_lo(.Lexit)(t0)     # t0 = IAT slot for kernel32.dll!ExitProcess
    jalr  ra, 0(t0)                     # ExitProcess(0), does not return

.Lhalt:                                 # defined fallthrough if it ever returned
    jal   zero, .Lhalt
